   691  static int
   692  pgp_parse_algo_attr_blob(const pgp_blob_t *blob, sc_cardctl_openpgp_keygen_info_t *key_info)
   693  {
   694          struct sc_object_id oid;
   695          unsigned int j;
   696
   697          if (blob == NULL || blob->data == NULL || blob->len == 0 ||
   698              blob->id < 0x00c1 || blob->id > 0x00c3 || key_info == NULL)
   699                  return SC_ERROR_INCORRECT_PARAMETERS;
   700
   701          key_info->key_id = blob->id - 0x00c0;   /* attribute algorithm blobs are C1 - C3 */
   702
   703          switch (blob->data[0]) {
   704                  case SC_OPENPGP_KEYALGO_RSA:
   705                          if (blob->len < 5)
   706                                  return SC_ERROR_INCORRECT_PARAMETERS;
   707
   708                          key_info->algorithm = SC_OPENPGP_KEYALGO_RSA;
   709                          key_info->u.rsa.modulus_len = bebytes2ushort(blob->data + 1);
   710                          key_info->u.rsa.exponent_len = bebytes2ushort(blob->data + 3);
   711
   712                          key_info->u.rsa.keyformat = (blob->len > 5)
   713                                                    ? blob->data[5]
   714                                                    : SC_OPENPGP_KEYFORMAT_RSA_STD;
   715                          break;
   716                  case SC_OPENPGP_KEYALGO_ECDH:
   717                  case SC_OPENPGP_KEYALGO_ECDSA:
   718
   719                          /* SC_OPENPGP_KEYALGO_ECDH || SC_OPENPGP_KEYALGO_ECDSA */
   720                          key_info->algorithm = blob->data[0];
   721
   722                          sc_init_oid(&oid);
   723                          /* Create copy of oid from blob */
   724                          for (j=0; j < (blob->len-1); j++) {
   725                                  oid.value[j] = blob->data[j+1]; /* ignore first byte of blob (algo ID) */
   726                          }
   727
   728                          /* compare with list of supported ec_curves */
   729                          for (j=0; ec_curves[j].oid.value[0] >= 0; j++){
   730                                  if (sc_compare_oid(&ec_curves[j].oid_binary, &oid)){
   731                                          key_info->u.ec.oid = ec_curves[j].oid;
   732                                          key_info->u.ec.key_length = ec_curves[j].size;
   733                                          break;
   734                                  }
   735                          }
   736                          break;
   737                  default:
   738                          return SC_ERROR_NOT_IMPLEMENTED;
   739          }
   740
   741          return SC_SUCCESS;
   742  }
